#include <iostream>
#include <vector>
#include <algorithm>

bool next_permutation_custom(std::vector<int>& idx) {
    int n = idx.size();
    for (int i = n - 1; i >= 1; --i) {
        if (idx[i] > idx[i-1]) {
            std::swap(idx[i], idx[i-1]);
            std::sort(idx.begin() + i, idx.end());
            return true;
        }
    }
    return false;
}

int main() {
    int n, a, b;
    std::cin >> n >> a >> b;

    std::vector<int> frames(6);
    std::vector<int> idxs(6);
    for (int i = 0; i < 6; ++i) {
        if (i < 4) {
            frames[i] = a;
        } else {
            frames[i] = b;
        }
        idxs[i] = i;
    }

    int bestAnswer = 6;
    while (true) {
        int count = 0;
        int leftover = 0;
        for (int i = 0; i < 6; ++i) {
            int frame_len = frames[idxs[i]];
            if (leftover < frame_len) {
                count++;
                leftover = n;
            }
            leftover -= frame_len;
        }
        if (count < bestAnswer) {
            bestAnswer = count;
        }
        if (!next_permutation_custom(idxs)) {
            break;
        }
    }

    std::cout << bestAnswer << std::endl;
    return 0;
}

